// ---- saved choices (theme / variant): survive a restart and reach the always-on screen ----
const dcGet = (k) => {
  try { const v = Number(zosFs.readFileSync({ path: 'dc_' + k + '.txt', options: { encoding: 'utf8' } })); if (v) return v } catch (e) {}
  try { if (typeof hmFS !== 'undefined') return Number(hmFS.SysProGetInt(k)) || 0 } catch (e) {}
  return 0
}
const dcSet = (k, v) => {
  try { zosFs.writeFileSync({ path: 'dc_' + k + '.txt', data: String(v), options: { encoding: 'utf8' } }) } catch (e) {}
  try { if (typeof hmFS !== 'undefined') hmFS.SysProSetInt(k, v) } catch (e) {}
}

WatchFace({
  initView() {
    // the picked variant survives a restart (when the watch offers storage)
    let variantIdx = 0
    variantIdx = dcGet('dialcraft_variant')

    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Background (FILL_RECT)
    ui.createWidget(ui.widget.FILL_RECT, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      color: 0x000000,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Scene (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: A('scene_basin.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Temperature (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(232),
      y: px(393),
      type: ui.data_type.WEATHER_CURRENT,
      font_array: img_Temperature_c49q,
      h_space: px(-9),
      align_h: ui.align.RIGHT,
      unit_en: A('degree.png'),
      unit_sc: A('degree.png'),
      unit_tc: A('degree.png'),
      negative_image: A('negative.png'),
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Ripple 1 (IMG)
    const variants_0 = [A('sp/rip_006.png'), A('sp/rip_001.png'), A('sp/rip_002.png'), A('sp/rip_003.png'), A('sp/rip_004.png'), A('sp/rip_005.png'), A('sp/rip_000.png')]
    const variant_0 = ui.createWidget(ui.widget.IMG, {
      x: px(166),
      y: px(322),
      src: variants_0[variantIdx % variants_0.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.ripA = variant_0
    F.ripA = variants_0

    // Ripple 2 (IMG)
    const variants_1 = [A('sp/rip_006.png'), A('sp/rip_001.png'), A('sp/rip_002.png'), A('sp/rip_003.png'), A('sp/rip_004.png'), A('sp/rip_005.png'), A('sp/rip_000.png')]
    const variant_1 = ui.createWidget(ui.widget.IMG, {
      x: px(166),
      y: px(322),
      src: variants_1[variantIdx % variants_1.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.ripB = variant_1
    F.ripB = variants_1

    // Splash (IMG)
    const variants_2 = [A('sp/splash_015.png'), A('sp/splash_008.png'), A('sp/splash_009.png'), A('sp/splash_010.png'), A('sp/splash_011.png'), A('sp/splash_012.png'), A('sp/splash_013.png'), A('sp/splash_014.png'), A('sp/splash_007.png')]
    const variant_2 = ui.createWidget(ui.widget.IMG, {
      x: px(191),
      y: px(292),
      src: variants_2[variantIdx % variants_2.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.splash = variant_2
    F.splash = variants_2

    // Drop (IMG)
    const variants_3 = [A('sp/drop_019.png'), A('sp/drop_017.png'), A('sp/drop_018.png'), A('sp/drop_016.png'), A('sp/drop_020.png')]
    const variant_3 = ui.createWidget(ui.widget.IMG, {
      x: px(241),
      y: px(178),
      src: variants_3[variantIdx % variants_3.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.drop = variant_3
    F.drop = variants_3

    // Minute Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(49),
      minute_startY: px(118),
      minute_zero: 1,
      minute_space: px(3),
      minute_align: ui.align.CENTER_H,
      minute_array: img_Minute_Main_6552,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Hour Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(49),
      hour_startY: px(14),
      hour_zero: 1,
      hour_space: px(3),
      hour_align: ui.align.CENTER_H,
      hour_array: img_Minute_Main_6552,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Minute (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(128),
      minute_startY: px(257),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_l538,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Hour (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(122),
      hour_startY: px(107),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_l5tr,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Weekday (IMG_WEEK)
    ui.createWidget(ui.widget.IMG_WEEK, {
      x: px(29),
      y: px(385),
      week_en: img_Weekday_ho87,
      week_sc: img_Weekday_ho87,
      week_tc: img_Weekday_ho87,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Day (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      day_startX: px(119),
      day_startY: px(393),
      day_zero: 0,
      day_space: px(-10),
      day_align: ui.align.LEFT,
      day_follow: 0,
      day_en_array: img_Day_io94,
      day_sc_array: img_Day_io94,
      day_tc_array: img_Day_io94,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // a Tap zone set to "Cycle variants" calls this
    const cycleVariants = () => {
      variantIdx = (variantIdx + 1) % Math.max(variants_0.length, variants_1.length, variants_2.length, variants_3.length)
      dcSet('dialcraft_variant', variantIdx)
      variant_0.setProperty(ui.prop.SRC, variants_0[variantIdx % variants_0.length])
      variant_1.setProperty(ui.prop.SRC, variants_1[variantIdx % variants_1.length])
      variant_2.setProperty(ui.prop.SRC, variants_2[variantIdx % variants_2.length])
      variant_3.setProperty(ui.prop.SRC, variants_3[variantIdx % variants_3.length])
    }

    // ---- user code (project.userCode) ----
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    {
      // Water Basin: every 6 s a drop forms on the leaf tip, falls, and splashes into the basin; two rings spread out and fade.
      // The impact is on every multiple of 6 seconds, so a drop lands exactly as the minute changes.
      const MS = 90;
      const V = {"ripA":{"__blank":0,"r1":1,"r2":2,"r3":3,"r4":4,"r5":5,"r0":6},"ripB":{"__blank":0,"r1":1,"r2":2,"r3":3,"r4":4,"r5":5,"r0":6},"splash":{"__blank":0,"s1":1,"s2":2,"s3":3,"s4":4,"s5":5,"s6":6,"s7":7,"s0":8},"drop":{"f":0,"b2":1,"b3":2,"b1":3,"__blank":4}};
      const P = 6, TI = 2.6;               // cycle length, the moment of impact in the cycle
      const FALL0 = 1.8, TIP_Y = 96, WATER_Y = 338, DX = 241, RX = 166, RY = 322;
      const tick = () => {
        const d = new Date(), t = d.getSeconds() + d.getMilliseconds() / 1000;
        const c = (t + TI) % P;            // c in [0,P): the drop is at the tip from c = 0 and lands at c = TI, i.e. when t is a multiple of 6
        // the drop
        if (c < FALL0) slot('drop')(DX, TIP_Y, V.drop[c < 0.6 ? 'b1' : c < 1.2 ? 'b2' : 'b3']);
        else if (c < TI) { const q = (c - FALL0) / (TI - FALL0); slot('drop')(DX, Math.round(TIP_Y + 8 + (WATER_Y - TIP_Y - 8) * q * q), V.drop.f); }
        else slot('drop').hide();
        // the splash and the rings after the impact (age = seconds since impact)
        const age = c >= TI ? c - TI : -1;
        if (age >= 0 && age < 0.88) slot('splash')(191, 292, V.splash['s' + Math.min(7, Math.floor(age / 0.11))]); else slot('splash').hide();
        const ring = (h, a) => { if (a >= 0 && a < 2.4) slot(h)(RX, RY, V[h]['r' + Math.min(5, Math.floor(a / 0.4))]); else slot(h).hide(); };
        ring('ripA', age);
        ring('ripB', age >= 0 ? age - 0.7 : -1);
      };
        // ---- shared runtime: slot setter that skips unchanged calls, and a loop that runs only while the face is on screen ----
      const SL = {};
      const slot = (h) => {
        if (SL[h]) return SL[h];
        const w = W[h], f = F[h]; let key = '';
        const s = (x, y, i, ww, hh) => {
          const k = x + '|' + y + '|' + i + '|' + ww + '|' + hh;
          if (k === key) return;
          key = k;
          const p = { x: pxv(x), y: pxv(y) };
          if (i !== undefined) p.src = f[i];
          if (ww !== undefined) { p.w = pxv(ww); p.h = pxv(hh); }
          w.setProperty(ui.prop.MORE, p);
        };
        s.hide = () => { if (key === 'hide') return; key = 'hide'; w.setProperty(ui.prop.MORE, { src: f[V[h].__blank] }); };
        return (SL[h] = s);
      };
      let gen = 0, running = false;
      const safe = () => { try { tick(); } catch (e) { /* a bad frame must not stop the loop */ } };
      const loop = (g) => {
        if (!running || g !== gen) return;
        safe();
        if (running && g === gen) { try { setTimeout(() => loop(g), MS); } catch (e) {} }
      };
      const start = () => {
        gen++; running = true; const g = gen;
        try { setTimeout(() => loop(g), MS); } catch (e) {}
        safe();
      };
      const stop = () => { running = false; gen++; };
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: start, pause_call: stop });
      start();

    }
  },

  build() {
    this.initView()
  },
})
